import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.Cs5aHXsR.js";var i=JSON.parse(`{"title":"Tools","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tools.md","filePath":"reference/tools.md","lastUpdated":1788355364000}`),a={name:`reference/tools.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to “Tools”">​</a></h1><p>Thirteen tools: six read, seven write. The write tools are <strong>not registered</strong> when <code>NTFY_READ_ONLY=true</code> — note that it defaults to <code>false</code>, so an unconfigured server offers all thirteen.</p><p>Beyond that, <code>NTFY_ALLOW_TOOLS</code> and <code>NTFY_DENY_TOOLS</code> narrow the list, and <code>NTFY_ALLOW_TOOLS=essential</code> selects the six marked <strong>essential</strong> below — see <a href="/guide/configuration#choosing-the-tools-that-load">choosing the tools that load</a>.</p><p>Five tools marked 👤 <strong>ask a person</strong> before they act: <code>delete_messages</code>, <code>delete_user</code>, <code>manage_user_access</code>, <code>create_user</code> and <code>update_message</code>. Where the MCP client supports elicitation that is a dialog the model cannot answer on its behalf; where it does not, the tool falls back to a short-lived, single-use <code>confirm_token</code> bound to the exact target. <code>ELICITATION=false</code> takes that fallback deliberately. See <a href="/guide/approval">Asking a person</a>.</p><p>Every tool declares all four MCP annotations — <code>readOnlyHint</code>, <code>destructiveHint</code>, <code>idempotentHint</code>, <code>openWorldHint</code>. <code>openWorldHint</code> is <code>false</code> throughout: this server talks to the one ntfy instance it is configured for.</p><p>Every tool also declares an <code>outputSchema</code> and answers with <code>structuredContent</code> beside the text block, so a client can use the result without parsing prose. The four tools that report what someone else wrote — <code>list_messages</code>, <code>get_message</code>, <code>get_account</code>, <code>list_users</code> — carry <code>untrusted: true</code> and <code>source: &quot;ntfy&quot;</code> as fields of the object, not only as a sentence in the text: a client that reads the structured half and ignores the text would otherwise get a publisher&#39;s prose with no framing at all. <code>get_server_info</code> does not carry the marker, because its sections are the instance&#39;s own configuration and counters rather than anything a third party published.</p><p>What this server builds is described exactly; what it passes on from ntfy is declared as an object with no fixed shape. The SDK validates every result against the schema before it goes out, so a schema stricter than the data would turn an upstream release that adds a field into a tool that fails outright.</p><p>Every tool that takes a topic falls back to the first entry of <code>NTFY_TOPICS</code> when it is omitted, and refuses a topic outside that list when it is set. The same list bounds the two access tools, which do not take a topic the ordinary way: <code>manage_user_access</code> refuses a grant pattern that reaches past it — <code>*</code> included — and <code>list_users</code> reports grants against the allowed topics only.</p><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to “At a glance”">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Kind</th><th>Preset</th><th>Notes</th></tr></thead><tbody><tr><td><code>list_messages</code></td><td>read</td><td><strong>essential</strong></td><td></td></tr><tr><td><code>get_message</code></td><td>read</td><td><strong>essential</strong></td><td></td></tr><tr><td><code>check_topic_access</code></td><td>read</td><td><strong>essential</strong></td><td>tests the read side only</td></tr><tr><td><code>get_server_info</code></td><td>read</td><td><strong>essential</strong></td><td>works before the credentials are right</td></tr><tr><td><code>get_account</code></td><td>read</td><td>—</td><td>projected to an allowlist of fields</td></tr><tr><td><code>list_users</code></td><td>read</td><td>—</td><td>admin</td></tr><tr><td><code>publish_message</code></td><td>write</td><td><strong>essential</strong></td><td></td></tr><tr><td><code>update_message</code> 👤</td><td>write</td><td><strong>essential</strong></td><td>asks a person</td></tr><tr><td><code>mark_messages_read</code></td><td>write</td><td>—</td><td></td></tr><tr><td><code>delete_messages</code> 👤</td><td>write</td><td>—</td><td>asks a person</td></tr><tr><td><code>create_user</code> 👤</td><td>write</td><td>—</td><td>admin, asks a person</td></tr><tr><td><code>delete_user</code> 👤</td><td>write</td><td>—</td><td>admin, asks a person</td></tr><tr><td><code>manage_user_access</code> 👤</td><td>write</td><td>—</td><td>admin, asks a person</td></tr></tbody></table><h2 id="read-tools" tabindex="-1">Read tools <a class="header-anchor" href="#read-tools" aria-label="Permalink to “Read tools”">​</a></h2><p>Registered always.</p><h3 id="list-messages" tabindex="-1">list_messages <a class="header-anchor" href="#list-messages" aria-label="Permalink to “list_messages”">​</a></h3><p><strong>essential</strong> — Polls the cached messages of one or more topics, oldest first.</p><p>Returns a <code>next_since</code> cursor: pass it back as <code>since</code> to get only what arrived after this call. Message bodies are shortened here; use <code>get_message</code> for one in full. Entries carrying an <code>updates</code> field revise an earlier notification rather than being new ones.</p><p>Retention is whatever the instance configures, 12 hours by default, so an empty result usually means &quot;nothing recent&quot; rather than &quot;no such topic&quot; — ntfy has no way to list the topics that exist.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>topics</code></td><td>string[] (1–10)</td><td>Topics to poll. Defaults to the first <code>NTFY_TOPICS</code> entry</td></tr><tr><td><code>since</code></td><td>string</td><td><code>all</code>, <code>latest</code>, <code>none</code>, a 12-character message id (exclusive), a Unix timestamp, or a duration such as <code>24h</code>. Defaults to <code>24h</code></td></tr><tr><td><code>id</code></td><td>string</td><td>Return only the message with this id</td></tr><tr><td><code>title</code></td><td>string (≤200)</td><td>Exact-match filter on the title</td></tr><tr><td><code>message</code></td><td>string (≤200)</td><td>Exact-match filter on the message body</td></tr><tr><td><code>priority</code></td><td>array (1–5)</td><td>Priorities to include — matches <strong>any</strong> of them</td></tr><tr><td><code>tags</code></td><td>string[] (1–10)</td><td>Tags to filter by — a message must carry <strong>all</strong> of them. The opposite of <code>priority</code></td></tr><tr><td><code>scheduled</code></td><td>boolean</td><td>Also include delayed messages that have not been delivered yet</td></tr><tr><td><code>limit</code></td><td>integer (1–200)</td><td>Most recent messages to return. Default 50</td></tr></tbody></table><p>All parameters are optional. The result is framed as untrusted data.</p><h3 id="get-message" tabindex="-1">get_message <a class="header-anchor" href="#get-message" aria-label="Permalink to “get_message”">​</a></h3><p><strong>essential</strong> — Fetches a single cached message in full, including the untruncated body, its action buttons and any attachment. Ids come from <code>list_messages</code> or from the result of <code>publish_message</code>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>The 12-character message id</td></tr><tr><td><code>topic</code></td><td>string</td><td>no</td><td>Topic to look in. Defaults to the first <code>NTFY_TOPICS</code> entry</td></tr></tbody></table><p>A message that is not in the cache is reported as such — it may have expired, or it was published to another topic.</p><h3 id="check-topic-access" tabindex="-1">check_topic_access <a class="header-anchor" href="#check-topic-access" aria-label="Permalink to “check_topic_access”">​</a></h3><p><strong>essential</strong> — Reports whether the configured credentials may <strong>subscribe</strong> to each topic, without publishing anything.</p><p>Read the result carefully: ntfy grants read and write separately, and the endpoint behind this tool tests the read side only. A write-only publishing token is denied here and can still publish perfectly well. A 401 or 403 therefore comes back with a note saying so rather than as a flat failure.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>topics</code></td><td>string[] (1–10)</td><td>no</td><td>Topics to check. Defaults to the first <code>NTFY_TOPICS</code> entry</td></tr></tbody></table><p>The topics are checked sequentially, not in parallel: repeated authentication failures trip ntfy&#39;s own auth rate limit, and a parallel fan-out is the fastest way to get there.</p><h3 id="get-server-info" tabindex="-1">get_server_info <a class="header-anchor" href="#get-server-info" aria-label="Permalink to “get_server_info”">​</a></h3><p><strong>essential</strong> — Health, capabilities and usage of the ntfy instance. Takes no parameters.</p><p>Health, config and stats are public on a default instance, so this is the one tool that works before the credentials are right — a good first call after setup. Each section is fetched independently; one that is unavailable is reported as such and does not fail the call. <code>version</code> needs an admin account, so its absence is normal.</p><p>The result also carries <code>admin_tools_available</code>, <code>authenticated_as</code> and <code>topics_restricted_to</code>, which answer &quot;should I try the user and access tools?&quot; and &quot;which topics may this server touch?&quot; from the same cheap call.</p><h3 id="get-account" tabindex="-1">get_account <a class="header-anchor" href="#get-account" aria-label="Permalink to “get_account”">​</a></h3><p>Identity, role, tier, limits and current usage of the configured credentials. Takes no parameters.</p><p><strong>The result is an allowlist, not a filtered copy.</strong> <code>username</code>, <code>role</code>, <code>tier</code>, <code>limits</code>, <code>stats</code>, <code>language</code> and the <em>metadata</em> of each access token are returned; everything else <code>GET /v1/account</code> sends is dropped. Access token values are overwritten with <code>(redacted)</code> — ntfy returns them in plaintext here — and the <code>sync_topic</code>, <code>phone_numbers</code>, <code>billing</code>, <code>reservations</code> and <code>subscriptions</code> fields never appear, the last two being lists of topic names and a topic name being a bearer secret.</p><h3 id="list-users" tabindex="-1">list_users <a class="header-anchor" href="#list-users" aria-label="Permalink to “list_users”">​</a></h3><p>Every account on the instance with its per-topic grants — the answer to &quot;who can read or write topic X&quot;. Requires an admin account; <code>get_server_info</code> reports whether the current one qualifies.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>username</code></td><td>string</td><td>Return only this account</td></tr><tr><td><code>topic</code></td><td>string</td><td>Return only accounts with a grant whose pattern matches this topic</td></tr><tr><td><code>limit</code></td><td>integer (1–500)</td><td>Accounts to return. Default 100</td></tr></tbody></table><p>All three are optional. Only <code>username</code>, <code>role</code>, <code>tier</code> and the grants are returned; whatever else ntfy sends is dropped rather than forwarded.</p><p>Where <code>NTFY_TOPICS</code> is set, the grants are restated against it: a grant appears once per allowed topic it covers, so a wildcard is reported as the topics this server may know about rather than verbatim, and a grant covering none of them is not shown. The <code>topic</code> filter is bounded by the same list.</p><h2 id="write-tools" tabindex="-1">Write tools <a class="header-anchor" href="#write-tools" aria-label="Permalink to “Write tools”">​</a></h2><p>Registered unless <code>NTFY_READ_ONLY=true</code>.</p><h3 id="publish-message" tabindex="-1">publish_message <a class="header-anchor" href="#publish-message" aria-label="Permalink to “publish_message”">​</a></h3><p><strong>essential</strong> — Sends a notification to one or more topics. At least one of <code>message</code> or <code>title</code> is required.</p><p>ntfy has no multi-topic publish, so this sends <strong>one request per topic</strong> and reports each outcome separately — check the <code>ok</code> field per entry rather than assuming the whole call worked. A rejection on one topic does not discard the ones that succeeded.</p><p>The returned id is also the notification&#39;s sequence id: pass it to <code>update_message</code> to revise this notification in place, which is how a progress report stays one notification instead of five.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>topics</code></td><td>string[] (1–10)</td><td>Topics to publish to. Defaults to the first <code>NTFY_TOPICS</code> entry</td></tr><tr><td><code>message</code></td><td>string (≤4096 B)</td><td>The notification body. Counted in bytes, not characters</td></tr><tr><td><code>title</code></td><td>string (≤250 B)</td><td>The notification title</td></tr><tr><td><code>priority</code></td><td>number or string</td><td>1 (min) to 5 (max), or <code>min</code>, <code>low</code>, <code>default</code>, <code>high</code>, <code>max</code> (<code>urgent</code> is accepted for max)</td></tr><tr><td><code>tags</code></td><td>string[] (≤20)</td><td>One tag per entry. A name matching an emoji short code renders as that emoji</td></tr><tr><td><code>click</code></td><td>string</td><td>URL opened when the notification itself is tapped. <code>http</code>/<code>https</code> only</td></tr><tr><td><code>icon</code></td><td>string</td><td>URL of a JPEG or PNG icon. <code>http</code>/<code>https</code> only</td></tr><tr><td><code>markdown</code></td><td>boolean</td><td>Render the message as Markdown in clients that support it</td></tr><tr><td><code>actions</code></td><td>array (≤3)</td><td>Action buttons — see below</td></tr><tr><td><code>attach</code></td><td>string</td><td>URL of a file to attach by reference. <code>http</code>/<code>https</code> only</td></tr><tr><td><code>filename</code></td><td>string (≤255)</td><td>Download name for the attachment. No path separators or control characters</td></tr><tr><td><code>delay</code></td><td>string</td><td>Deliver later: a duration such as <code>30m</code>, a Unix timestamp, or <code>tomorrow, 10am</code>. 10 seconds to 3 days</td></tr><tr><td><code>cache</code></td><td>boolean</td><td><code>false</code> keeps the message out of the server cache</td></tr><tr><td><code>firebase</code></td><td>boolean</td><td><code>false</code> skips forwarding via Firebase</td></tr></tbody></table><p>All parameters are optional; the constraint is that <code>message</code> or <code>title</code> is present.</p><p><code>cache: false</code> means the notification reaches only the clients connected at that moment and can afterwards be neither updated nor deleted. Combining it with <code>delay</code> is refused with an explanation — a delayed message has to exist on the server until it fires.</p><p><code>cache</code> and <code>firebase</code> are booleans here and strings in ntfy&#39;s JSON body, which wants the literal <code>&quot;no&quot;</code> and silently ignores <code>false</code>. The mapping happens in the server, which is the only shape a model cannot get wrong.</p><h4 id="action-buttons" tabindex="-1">Action buttons <a class="header-anchor" href="#action-buttons" aria-label="Permalink to “Action buttons”">​</a></h4><p>Up to three; a fourth is rejected by ntfy. Every action takes a <code>label</code> (1–64 characters) and an optional <code>clear</code> boolean, plus:</p><table tabindex="0"><thead><tr><th><code>action</code></th><th>Fields</th></tr></thead><tbody><tr><td><code>view</code></td><td><code>url</code> — opens it on the device</td></tr><tr><td><code>http</code></td><td><code>url</code>, <code>method</code> (GET, POST, PUT, PATCH, DELETE — <strong>POST by default</strong>), <code>headers</code>, <code>body</code></td></tr><tr><td><code>copy</code></td><td><code>value</code> (≤4096 characters) — copies it to the clipboard</td></tr><tr><td><code>broadcast</code></td><td><code>intent</code>, <code>extras</code> — Android only</td></tr></tbody></table><p>An <code>http</code> action fires from the recipient&#39;s device, not from the server. <code>url</code> must be <code>http</code> or <code>https</code> for the same reason.</p><h3 id="update-message-👤" tabindex="-1">update_message 👤 <a class="header-anchor" href="#update-message-👤" aria-label="Permalink to “update_message 👤”">​</a></h3><p><strong>essential</strong> — <strong>Asks a person first.</strong> Replaces the content of a notification already published, so subscribers see it change in place instead of receiving another one. At least one content field is required.</p><p>Gated because from ntfy 2.16 the revision replaces the notification <strong>on the subscribers&#39; devices</strong>: the text they were shown survives nowhere but this server&#39;s cache. <code>actions</code> travels with the content fields, and an <code>http</code> button fires from the recipient&#39;s phone — so an unguarded update could turn a delivered alert into a button that calls something. What is confirmed is the notification, not the new text.</p><p>The sequence id is the id returned by <code>publish_message</code>, and it only exists for cached messages: one published with <code>cache: false</code> cannot be updated. Only the fields given are sent. The cache keeps each revision as its own entry pointing back at the original, which is why <code>list_messages</code> shows them with an <code>updates</code> field.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>sequence_id</code></td><td>string</td><td>yes</td><td>Id of the notification to revise, from <code>publish_message</code></td></tr><tr><td><code>topic</code></td><td>string</td><td>no</td><td>Its topic. Defaults to the first <code>NTFY_TOPICS</code> entry</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>The token from this tool&#39;s previous, unconfirmed response</td></tr></tbody></table><p>Plus the content fields of <code>publish_message</code>: <code>message</code>, <code>title</code>, <code>priority</code>, <code>tags</code>, <code>click</code>, <code>icon</code>, <code>markdown</code> and <code>actions</code>. The publish-only fields (<code>attach</code>, <code>filename</code>, <code>delay</code>, <code>cache</code>, <code>firebase</code>) are not part of an update.</p><h3 id="mark-messages-read" tabindex="-1">mark_messages_read <a class="header-anchor" href="#mark-messages-read" aria-label="Permalink to “mark_messages_read”">​</a></h3><p>Clears notifications on subscribers&#39; devices. The messages stay in the server cache and remain readable with <code>list_messages</code>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>sequence_ids</code></td><td>string[] (1–25)</td><td>yes</td><td>Ids of the notifications to clear</td></tr><tr><td><code>topic</code></td><td>string</td><td>no</td><td>Their topic. Defaults to the first <code>NTFY_TOPICS</code> entry</td></tr></tbody></table><p>Each id is reported separately, so one failure does not hide the successes.</p><h3 id="delete-messages-👤" tabindex="-1">delete_messages 👤 <a class="header-anchor" href="#delete-messages-👤" aria-label="Permalink to “delete_messages 👤”">​</a></h3><p><strong>Asks a person first.</strong> Deletes notifications and cancels scheduled ones that have not been delivered yet.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>sequence_ids</code></td><td>string[] (1–25)</td><td>yes</td><td>Ids of the notifications to delete</td></tr><tr><td><code>topic</code></td><td>string</td><td>no</td><td>Their topic. Defaults to the first <code>NTFY_TOPICS</code> entry</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>The token from this tool&#39;s previous, unconfirmed response</td></tr></tbody></table><p>Where the client can show a dialog, one is raised and <code>confirm_token</code> is never offered. Where it cannot, call once without it to receive the token, then again with it. Either way the approval is bound to a fingerprint of the exact set of ids, so one obtained for a single message cannot execute a longer list.</p><h3 id="create-user-👤" tabindex="-1">create_user 👤 <a class="header-anchor" href="#create-user-👤" aria-label="Permalink to “create_user 👤”">​</a></h3><p><strong>Asks a person first.</strong> Creates a <strong>non-admin</strong> account on a self-hosted instance. Requires an admin account. The API cannot create administrators; only the ntfy command line can (<code>ntfy user add --role=admin</code>).</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>username</code></td><td>string (≤64)</td><td>yes</td><td>The account name</td></tr><tr><td><code>password</code></td><td>string (8–128)</td><td>yes</td><td>Initial password</td></tr><tr><td><code>tier</code></td><td>string (≤64)</td><td>no</td><td>Tier name, on an instance that defines tiers</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Only on the fallback path</td></tr></tbody></table><p>A new account can reach nothing until <code>manage_user_access</code> grants it a topic. It is asked about all the same, as the mirror image of <code>delete_user</code>: bringing an account into existence is a change to who may reach this instance, which no annotation carries.</p><p>Be aware that a password passed as a tool argument stays in the conversation transcript — for an account that matters, create it on the server instead. The password is not echoed back in the result, is not in the confirmation prompt, and is not part of the token&#39;s binding: what the approval is about is the account name.</p><h3 id="delete-user-👤" tabindex="-1">delete_user 👤 <a class="header-anchor" href="#delete-user-👤" aria-label="Permalink to “delete_user 👤”">​</a></h3><p><strong>Asks a person first.</strong> Removes an account and every access grant attached to it. Requires an admin account.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>username</code></td><td>string (≤64)</td><td>yes</td><td>The account to remove</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>The token from this tool&#39;s previous, unconfirmed response</td></tr></tbody></table><h3 id="manage-user-access-👤" tabindex="-1">manage_user_access 👤 <a class="header-anchor" href="#manage-user-access-👤" aria-label="Permalink to “manage_user_access 👤”">​</a></h3><p><strong>Asks a person first.</strong> Sets or removes an account&#39;s access to a topic or topic pattern. Requires an admin account.</p><p>Destructive in both directions, which is why it is gated: taking access away breaks a running publisher, and granting it exposes a topic&#39;s traffic to another account.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>username</code></td><td>string (≤64)</td><td>yes</td><td>The account to change</td></tr><tr><td><code>topic</code></td><td>string (≤64)</td><td>yes</td><td>A topic name, or a prefix ending in <code>*</code></td></tr><tr><td><code>action</code></td><td>enum</td><td>yes</td><td>See below</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>The token from this tool&#39;s previous, unconfirmed response</td></tr></tbody></table><table tabindex="0"><thead><tr><th><code>action</code></th><th>Effect</th></tr></thead><tbody><tr><td><code>read_write</code></td><td>Read and write the topic</td></tr><tr><td><code>read_only</code></td><td>Subscribe only</td></tr><tr><td><code>write_only</code></td><td>Publish only</td></tr><tr><td><code>deny</code></td><td>An explicit refusal — the only way to carve an exception out of a wildcard</td></tr><tr><td><code>revoke</code></td><td>Removes the rule entirely, so a broader wildcard or the server default applies again</td></tr></tbody></table><p>Five unambiguous names rather than ntfy&#39;s nine aliases for four permissions (<code>rw</code>, <code>read-write</code>, <code>ro</code>, <code>read</code>, <code>read-only</code>, …), which is nine ways for a model to be almost right. <code>deny</code> and <code>revoke</code> really are different, and both are needed.</p><p>Where <code>NTFY_TOPICS</code> restricts this server, <code>topic</code> must be one of its entries and a wildcard is refused before the question reaches anyone. A grant is permanent access to every topic the pattern covers, including topics that do not exist yet, and no finite allowlist covers a wildcard.</p><p>The confirmation token is bound to the three arguments <strong>in order</strong>, because their vocabularies overlap: a token approved for one account-and-topic pair must not execute the reverse pair.</p>`,83)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};